import React, { useId, useState } from 'react';
import { Link as RouterLink } from 'react-router-dom';
import {
  Accordion,
  AccordionDetails,
  AccordionSummary,
  Alert,
  Box,
  Chip,
  Link,
  Paper,
  Stack,
  Button,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Typography,
} from '@mui/material';
import ExpandMoreIcon from '@mui/icons-material/ExpandMore';
import { alpha, type Theme } from '@mui/material/styles';
import type { SxProps } from '@mui/system';

import {
  labelDataQualityTier,
  labelQuantificationMethod,
  formatComplianceFlags,
} from '../../shared/carbonCalculationLabels';
import {
  buildTransactionCalculationReadout,
  type CalculationFootprintInput,
} from '../../utils/transactionCalculationReadout';
import {
  CALCULATION_TONE_STYLE,
  resolveCalculationTone,
  tierChipColor,
} from '../../utils/calculationMethodTone';

export type TransactionCarbonFootprintDetails = CalculationFootprintInput;

interface TransactionCalculationDetailsProps {
  footprint?: TransactionCarbonFootprintDetails | null;
  transactionType?: string;
  category?: string;
  subcategory?: string;
  ownership?: string;
  amount?: number;
  currency?: string;
  quantity?: number;
  unit?: string;
  description?: string;
  dense?: boolean;
  afterDiscrepancies?: React.ReactNode;
}

const proseWrapSx = {
  whiteSpace: 'normal',
  overflowWrap: 'break-word',
  wordBreak: 'normal',
} as const;

const intactValueSx = {
  whiteSpace: 'nowrap',
  fontVariantNumeric: 'tabular-nums',
} as const;

const sectionScrollSx = {
  scrollMarginTop: 8,
} as const;

const KEY_WORKSHEET_STEPS = new Set([
  'Direct emissions',
  'Calculated total',
  'Scope split',
  'Emission factor citation',
  'Uncertainty band',
  'Check against the stored result',
]);

const VERIFICATION_PATTERN = /^Recomputed result (.+?) (matches|does not match) the (.+?) figure\. Difference (.+?) kg CO₂e, (within|outside) ±(.+?) kg CO₂e\.$/;

const splitHeadline = (headline: string): { value: string; unit: string; suffix: string } | null => {
  const match = headline.match(/^([\d,.\s]+?)\s+(kg CO₂e)(.*)$/);
  if (!match) return null;
  return {
    value: match[1].trim(),
    unit: match[2],
    suffix: match[3].trim(),
  };
};

const tableScrollSx = {
  overflowX: 'auto',
  overflowY: 'hidden',
  maxWidth: '100%',
} as const;

type WorksheetSection = 'result' | 'worksheet' | 'factors' | 'json';

const sectionNavButtonSx = (active: boolean): SxProps<Theme> => ({
  minWidth: 0,
  lineHeight: 1.3,
  fontWeight: active ? 700 : 600,
  borderRadius: 1,
  color: active ? 'text.primary' : 'text.secondary',
  bgcolor: (theme) => (
    active
      ? alpha(theme.palette.primary.main, theme.palette.mode === 'dark' ? 0.22 : 0.14)
      : 'transparent'
  ),
  '&.MuiButton-root': {
    minHeight: 30,
    padding: '4px 10px',
    boxShadow: (theme) => (active ? `inset 0 -2px 0 ${theme.palette.primary.main}` : 'none'),
  },
  '&.MuiButton-root:hover': {
    boxShadow: (theme) => (active ? `inset 0 -2px 0 ${theme.palette.primary.main}` : 'none'),
    bgcolor: (theme) => alpha(
      theme.palette.primary.main,
      active
        ? (theme.palette.mode === 'dark' ? 0.3 : 0.2)
        : (theme.palette.mode === 'dark' ? 0.12 : 0.08),
    ),
  },
  '&.MuiButton-root.Mui-focusVisible': {
    outline: '2px solid',
    outlineColor: 'primary.light',
    outlineOffset: 2,
  },
});

const flagChipSx = {
  height: 'auto',
  maxWidth: '100%',
  '& .MuiChip-label': {
    display: 'block',
    whiteSpace: 'normal',
    overflowWrap: 'break-word',
    lineHeight: 1.35,
    py: 0.5,
  },
} as const;

const httpUrl = (value: unknown): string | null => {
  const text = String(value ?? '').trim();
  if (!text) return null;
  try {
    const url = new URL(text);
    if (url.protocol === 'http:' || url.protocol === 'https:') return url.href;
  } catch {
    return null;
  }
  return null;
};

const keepValueIntact = (value: string): boolean => {
  const text = value.trim();
  if (!text || text === '—') return true;
  if (text.length > 72) return false;
  if (!/\d|₹/.test(text)) return false;
  if (text.split(/\s+/).length > 10) return false;
  return true;
};

const SourceText: React.FC<{ value: string }> = ({ value }) => {
  const href = httpUrl(value);
  if (!href) return <>{value}</>;
  return (
    <Link href={href} target="_blank" rel="noopener noreferrer" sx={proseWrapSx}>
      {value}
    </Link>
  );
};

const isSalesReviewCandidate = (
  transactionType?: string,
  category?: string,
  exclusionReason?: string
): boolean => {
  const type = String(transactionType || '').toLowerCase();
  const cat = String(category || '').toLowerCase();
  if (type === 'sale' || cat === 'sales' || cat === 'revenue') return true;
  if (exclusionReason === 'revenue_or_sales_non_emitting') return true;
  return false;
};

const toComplianceFlagRecord = (
  flags?: string[] | Record<string, boolean>
): Record<string, boolean> => {
  if (Array.isArray(flags)) {
    return Object.fromEntries(flags.map((flag) => [String(flag), true]));
  }
  return flags || {};
};

export const TransactionCalculationDetails: React.FC<TransactionCalculationDetailsProps> = ({
  footprint,
  transactionType,
  category,
  subcategory,
  ownership,
  amount,
  currency,
  quantity,
  unit,
  description,
  dense = false,
  afterDiscrepancies,
}) => {
  const uid = useId();
  const resultId = `${uid}-result`;
  const worksheetId = `${uid}-worksheet`;
  const factorsId = `${uid}-factors`;
  const jsonId = `${uid}-json`;
  const [factorsOpen, setFactorsOpen] = useState(false);
  const [jsonOpen, setJsonOpen] = useState(false);
  const [activeSection, setActiveSection] = useState<WorksheetSection>('result');

  if (!footprint) {
    return (
      <Typography variant="body2" color="text.secondary">
        No calculation details available.
      </Typography>
    );
  }

  const calculationTone = resolveCalculationTone(footprint);
  const toneStyle = calculationTone ? CALCULATION_TONE_STYLE[calculationTone] : null;
  const readout = buildTransactionCalculationReadout(footprint, {
    amount,
    currency,
    category,
    subcategory,
    quantity,
    unit,
    description,
    ownership,
  });
  const workedRows = (footprint.calculationRecord?.workedSteps || [])
    .filter((step) => step.substitution || step.expression)
    .map((step) => ({
      step: step.label || step.id || 'Step',
      calculation: step.substitution || step.expression || '',
      result: step.result == null ? '—' : `${step.result}${step.unit ? ` ${step.unit}` : ''}`,
      note: step.note || undefined,
    }));
  const worksheet = (workedRows.length > 0 ? workedRows : readout.worksheet);
  const worksheetRows = worksheet.length > 0
    ? worksheet
    : readout.steps.map((step) => ({
      step: 'Calculation',
      calculation: step,
      result: '—',
      note: undefined,
    }));
  const flags = formatComplianceFlags(toComplianceFlagRecord(footprint.complianceFlags));
  const salesReview = isSalesReviewCandidate(transactionType, category, footprint.exclusionReason);
  const normalizedCategory = String(category || '').toLowerCase();
  const usesMaintenanceProxy =
    normalizedCategory === 'maintenance'
    || (
      normalizedCategory === 'equipment'
      && ['spend_proxy', 'spend-proxy', 'tier_2_spend'].includes(
        String(footprint.quantificationMethod || footprint.calculationMethod || '').toLowerCase()
      )
    );
  const showJson = Boolean(footprint.calculationRecord?.formula);
  const scrollToSection = (sectionId: string, panel?: 'factors' | 'json') => {
    if (panel === 'factors') setFactorsOpen(true);
    if (panel === 'json') setJsonOpen(true);
    window.requestAnimationFrame(() => {
      const target = document.getElementById(sectionId);
      if (!target) return;
      const dialog = target.closest('[role="dialog"]');
      let scroller: HTMLElement | null = target.parentElement;
      while (scroller && (!dialog || dialog.contains(scroller) || scroller === dialog)) {
        const overflowY = window.getComputedStyle(scroller).overflowY;
        if (/(auto|scroll)/.test(overflowY) && scroller.scrollHeight > scroller.clientHeight + 1) break;
        if (dialog && scroller === dialog) {
          scroller = null;
          break;
        }
        scroller = scroller.parentElement;
      }
      if (!scroller) return;
      const delta = target.getBoundingClientRect().top - scroller.getBoundingClientRect().top;
      const reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      scroller.scrollTo({
        top: scroller.scrollTop + delta - 8,
        behavior: reduceMotion ? 'auto' : 'smooth',
      });
    });
  };
  const selectSection = (section: WorksheetSection, sectionId: string, panel?: 'factors' | 'json') => {
    setActiveSection(section);
    scrollToSection(sectionId, panel);
  };

  return (
    <Box data-testid="advanced-carbon-calculation" sx={{ minWidth: 0 }}>
      <Stack
        component="nav"
        aria-label="Worksheet sections"
        direction="row"
        flexWrap="wrap"
        useFlexGap
        spacing={0.5}
        sx={{ position: 'static', minWidth: 0 }}
      >
        <Button
          size="small"
          variant="text"
          aria-current={activeSection === 'result' ? 'location' : undefined}
          sx={sectionNavButtonSx(activeSection === 'result')}
          onClick={() => selectSection('result', resultId)}
        >
          Result
        </Button>
        <Button
          size="small"
          variant="text"
          aria-current={activeSection === 'worksheet' ? 'location' : undefined}
          sx={sectionNavButtonSx(activeSection === 'worksheet')}
          onClick={() => selectSection('worksheet', worksheetId)}
        >
          Worksheet
        </Button>
        <Button
          size="small"
          variant="text"
          aria-current={activeSection === 'factors' ? 'location' : undefined}
          sx={sectionNavButtonSx(activeSection === 'factors')}
          onClick={() => selectSection('factors', factorsId, 'factors')}
        >
          Factors
        </Button>
        {showJson && (
          <Button
            size="small"
            variant="text"
            aria-current={activeSection === 'json' ? 'location' : undefined}
            sx={sectionNavButtonSx(activeSection === 'json')}
            onClick={() => selectSection('json', jsonId, 'json')}
          >
            JSON
          </Button>
        )}
      </Stack>
      <Stack spacing={dense ? 1.5 : 2} sx={{ mt: 1.5, minWidth: 0 }}>

      <Paper id={resultId} variant="outlined" sx={{ p: dense ? 1.5 : 2, ...sectionScrollSx }}>
        <Typography variant="overline" color="text.secondary">
          Calculated result
        </Typography>
        <Box sx={{ maxWidth: '100%', mt: 0.5, overflowX: 'auto', overflowY: 'hidden' }}>
          {(() => {
            const headlineParts = splitHeadline(readout.headline);
            if (!headlineParts) {
              return (
                <Typography variant="h4" component="p" sx={{ fontWeight: 700, lineHeight: 1.15, ...intactValueSx }}>
                  {readout.headline}
                </Typography>
              );
            }
            return (
              <Stack direction="row" alignItems="baseline" flexWrap="wrap" useFlexGap spacing={1}>
                <Typography variant="h4" component="p" sx={{ fontWeight: 700, lineHeight: 1.05, ...intactValueSx }}>
                  {headlineParts.value}
                </Typography>
                <Typography variant="h6" component="p" sx={{ fontWeight: 600, lineHeight: 1.2, ...intactValueSx }}>
                  {headlineParts.unit}
                </Typography>
                {headlineParts.suffix ? (
                  <Typography variant="body2" component="p" color="text.secondary" sx={intactValueSx}>
                    {headlineParts.suffix}
                  </Typography>
                ) : null}
              </Stack>
            );
          })()}
        </Box>
        <Stack direction="row" flexWrap="wrap" gap={0.75} sx={{ mt: 1, minWidth: 0 }}>
          <Chip
            size="small"
            color={toneStyle?.chipColor || 'default'}
            label={labelQuantificationMethod(footprint.quantificationMethod || footprint.calculationMethod)}
            sx={{ maxWidth: '100%' }}
          />
          <Chip
            size="small"
            variant="outlined"
            color={tierChipColor(footprint.dataQualityTier)}
            label={labelDataQualityTier(footprint.dataQualityTier)}
            sx={{ maxWidth: '100%' }}
          />
        </Stack>
        <Typography variant="body2" sx={{ mt: 1.5, ...proseWrapSx }}>
          {readout.inlineFormula || readout.summary}
        </Typography>
      </Paper>

      {normalizedCategory === 'maintenance' && ['spend_proxy', 'spend-proxy', 'tier_2_spend'].includes(
        String(footprint.quantificationMethod || footprint.calculationMethod || '').toLowerCase()
      ) && (
        <Alert severity="info">
          This maintenance row has a rupee amount and no counted jobs, so it is a spend proxy (amount ÷ ₹ per service unit × 0.1 kg CO₂e) and counts in the 1% estimate check. Enter Quantity with unit service_unit, visit, or job so the jobs are activity-based. A named refrigerant uses kg. Named parts such as steel use kg. The ₹ rate under{' '}
          <Link component={RouterLink} to="/msme-profile#carbon-methodology">
            My company → Carbon methodology settings
          </Link>
          {' '}changes the screening kilograms.
        </Alert>
      )}
      {usesMaintenanceProxy && normalizedCategory === 'equipment' && (
        <Alert severity="info">
          Maintenance emissions use a ₹/service-unit proxy. Adjust the unit price under{' '}
          <Link component={RouterLink} to="/msme-profile#carbon-methodology">
            My company → Carbon methodology settings
          </Link>
          .
        </Alert>
      )}
      {salesReview && (
        <Alert severity="warning">
          This transaction looks like sales or revenue. Compliance inventory excludes non-emitting
          sales flows — review classification if it represents purchased goods or services.
        </Alert>
      )}
      {flags.length > 0 && (
        <Stack direction="row" flexWrap="wrap" gap={0.5} sx={{ minWidth: 0, maxWidth: '100%' }}>
          {flags.map((flag: string) => (
            <Chip key={flag} size="small" label={flag} variant="outlined" color="warning" sx={flagChipSx} />
          ))}
        </Stack>
      )}

      {Array.isArray(footprint.calculationDiscrepancies) && footprint.calculationDiscrepancies.length > 0 && (
        <Alert severity="warning" sx={{ py: 0.5 }}>
          <Typography variant="subtitle2" sx={{ fontWeight: 700, mb: 0.5 }}>
            Add these details, in this order
          </Typography>
          <Stack component="ol" spacing={0.5} sx={{ m: 0, pl: 2 }}>
            {footprint.calculationDiscrepancies.map((entry) => (
              <Typography key={entry.id} component="li" variant="body2" sx={proseWrapSx}>
                {entry.request}
              </Typography>
            ))}
          </Stack>
        </Alert>
      )}

      {afterDiscrepancies}

      <Paper id={worksheetId} variant="outlined" sx={{ p: dense ? 1.5 : 2, ...sectionScrollSx }}>
        <Typography variant="subtitle2" gutterBottom>
          Auditor verification worksheet
        </Typography>
        <Typography variant="body2" color="text.secondary" sx={{ mb: 1, ...proseWrapSx }}>
          Each line substitutes the stored quantity, price, and emission factor so the kg CO₂e result can be recomputed.
        </Typography>
        {readout.verification && (
          <Alert
            severity={footprint.calculationRecord?.validation?.withinTolerance === false ? 'warning' : 'success'}
            sx={{ mb: 1.5 }}
          >
            {(() => {
              const scanned = readout.verification.match(VERIFICATION_PATTERN);
              if (!scanned) return readout.verification;
              const scanItems = [
                { label: 'Recomputed result', value: scanned[1] },
                { label: 'Difference', value: `${scanned[4]} kg CO₂e` },
                { label: 'Tolerance', value: `±${scanned[6]} kg CO₂e` },
              ];
              return (
                <Stack spacing={1} sx={{ minWidth: 0 }}>
                  <Stack direction="row" flexWrap="wrap" useFlexGap spacing={2}>
                    {scanItems.map((item) => (
                      <Box key={item.label} sx={{ minWidth: 0 }}>
                        <Typography variant="caption" component="div" sx={{ opacity: 0.85 }}>
                          {item.label}
                        </Typography>
                        <Typography variant="body1" component="div" sx={{ fontWeight: 700, ...intactValueSx }}>
                          {item.value}
                        </Typography>
                      </Box>
                    ))}
                  </Stack>
                  <Typography variant="body2" sx={proseWrapSx}>
                    {readout.verification}
                  </Typography>
                </Stack>
              );
            })()}
          </Alert>
        )}
        <TableContainer sx={tableScrollSx}>
          <Table size="small" aria-label="Auditor verification worksheet" sx={{ minWidth: 640 }}>
            <TableHead>
              <TableRow>
                <TableCell sx={{ fontWeight: 700, minWidth: 160, width: '26%', bgcolor: 'action.hover', ...proseWrapSx }}>Step</TableCell>
                <TableCell sx={{ fontWeight: 700, minWidth: 280, bgcolor: 'action.hover', ...proseWrapSx }}>Substituted calculation</TableCell>
                <TableCell align="right" sx={{ fontWeight: 700, minWidth: 168, bgcolor: 'action.hover', ...intactValueSx }}>Result</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {worksheetRows.map((row) => {
                const noteHref = row.note ? httpUrl(row.note) : null;
                const showNote = Boolean(row.note) && row.note !== readout.verification;
                const keyStep = KEY_WORKSHEET_STEPS.has(row.step);
                const closingStep = row.step === 'Calculated total' || row.step === 'Check against the stored result';
                const rowPadding = keyStep ? 1.25 : undefined;
                return (
                  <TableRow
                    key={`${row.step}-${row.calculation}`}
                    sx={row.step === 'Calculated total' ? { bgcolor: 'action.hover' } : undefined}
                  >
                    <TableCell
                      sx={{
                        fontWeight: keyStep ? 700 : 600,
                        verticalAlign: 'top',
                        py: rowPadding,
                        ...(closingStep ? { borderTop: '2px solid', borderTopColor: 'divider' } : {}),
                        ...proseWrapSx,
                      }}
                    >
                      {row.step}
                    </TableCell>
                    <TableCell
                      sx={{
                        verticalAlign: 'top',
                        py: rowPadding,
                        ...(closingStep ? { borderTop: '2px solid', borderTopColor: 'divider' } : {}),
                        ...proseWrapSx,
                      }}
                    >
                      {row.calculation}
                      {showNote ? (
                        <Typography variant="caption" color="text.secondary" display="block" sx={proseWrapSx}>
                          {noteHref ? <SourceText value={row.note || ''} /> : row.note}
                        </Typography>
                      ) : null}
                    </TableCell>
                    <TableCell
                      align="right"
                      sx={{
                        verticalAlign: 'top',
                        py: rowPadding,
                        fontWeight: keyStep ? 700 : undefined,
                        fontSize: row.step === 'Calculated total' ? '0.95rem' : undefined,
                        ...(closingStep ? { borderTop: '2px solid', borderTopColor: 'divider' } : {}),
                        ...intactValueSx,
                      }}
                    >
                      {row.result}
                    </TableCell>
                  </TableRow>
                );
              })}
            </TableBody>
          </Table>
        </TableContainer>
      </Paper>

      <Accordion
        id={factorsId}
        disableGutters
        variant="outlined"
        expanded={factorsOpen}
        onChange={(_event, expanded) => setFactorsOpen(expanded)}
        sx={sectionScrollSx}
      >
        <AccordionSummary expandIcon={<ExpandMoreIcon />} aria-controls="advanced-factors" id="advanced-factors-header">
          <Box sx={{ minWidth: 0 }}>
            <Typography variant="subtitle2">Factors, prices, and sources</Typography>
            <Typography variant="caption" color="text.secondary" sx={proseWrapSx}>
              Every factor, price, source, and uncertainty stored on this calculation
            </Typography>
          </Box>
        </AccordionSummary>
        <AccordionDetails>
          <Stack spacing={2}>
            {readout.groups.map((group) => (
              <Box key={group.title}>
                <Typography
                  variant="caption"
                  color="text.secondary"
                  sx={{ fontWeight: 700, letterSpacing: 0.6, textTransform: 'uppercase' }}
                >
                  {group.title}
                </Typography>
                <TableContainer sx={tableScrollSx}>
                  <Table size="small" aria-label={group.title} sx={{ minWidth: 480 }}>
                    <TableBody>
                      {group.rows.map((row) => {
                        const valueText = String(row.value ?? '');
                        const numericValue = /\d/.test(valueText) && /^[\d.,\s%₹+\-–—/×x]+$/.test(valueText.trim());
                        const intact = keepValueIntact(valueText);
                        return (
                          <TableRow key={`${group.title}-${row.label}`}>
                            <TableCell
                              sx={{
                                width: '38%',
                                minWidth: 140,
                                fontWeight: 600,
                                verticalAlign: 'top',
                                borderColor: 'divider',
                                color: 'text.secondary',
                                py: 0.75,
                                ...proseWrapSx,
                              }}
                            >
                              {row.label}
                            </TableCell>
                            <TableCell
                              align={numericValue ? 'right' : 'left'}
                              sx={{
                                borderColor: 'divider',
                                py: 0.75,
                                verticalAlign: 'top',
                                ...(intact ? intactValueSx : proseWrapSx),
                              }}
                            >
                              <SourceText value={valueText} />
                            </TableCell>
                          </TableRow>
                        );
                      })}
                    </TableBody>
                  </Table>
                </TableContainer>
              </Box>
            ))}
          </Stack>
        </AccordionDetails>
      </Accordion>

      {showJson && footprint.calculationRecord && (
        <Accordion
          id={jsonId}
          disableGutters
          variant="outlined"
          expanded={jsonOpen}
          onChange={(_event, expanded) => setJsonOpen(expanded)}
          sx={sectionScrollSx}
        >
          <AccordionSummary expandIcon={<ExpandMoreIcon />}>
            <Typography variant="subtitle2">Calculation JSON for validation</Typography>
          </AccordionSummary>
          <AccordionDetails>
            <Stack spacing={1.5} sx={{ minWidth: 0 }}>
              <Typography variant="body2" sx={proseWrapSx}>
                Formula: <strong>{footprint.calculationRecord.formula}</strong>
              </Typography>
              {footprint.calculationRecord.validation?.withinTolerance != null && (
                <Typography variant="body2" color="text.secondary" sx={proseWrapSx}>
                  Recomputed result {footprint.calculationRecord.results?.calculatedKgCo2e ?? '—'} kg CO₂e.
                  {' '}Difference from the {footprint.calculationRecord.validation.comparedTo} figure is{' '}
                  {footprint.calculationRecord.validation.differenceKgCo2e ?? '—'} kg CO₂e.
                </Typography>
              )}
              {footprint.calculationRecord.variables && (
                <TableContainer sx={tableScrollSx}>
                  <Table size="small" aria-label="Calculation variables" sx={{ minWidth: 420 }}>
                    <TableBody>
                      {Object.entries(footprint.calculationRecord.variables).map(([name, variable]) => {
                        const valueLabel = `${String(variable?.value ?? '')}${variable?.unit ? ` ${variable.unit}` : ''}`;
                        return (
                          <TableRow key={name}>
                            <TableCell sx={{ fontWeight: 600, width: '38%', minWidth: 140, color: 'text.secondary', borderColor: 'divider', ...proseWrapSx }}>{name}</TableCell>
                            <TableCell
                              align="right"
                              sx={{
                                borderColor: 'divider',
                                ...(keepValueIntact(valueLabel) ? intactValueSx : proseWrapSx),
                              }}
                            >
                              {valueLabel}
                            </TableCell>
                          </TableRow>
                        );
                      })}
                    </TableBody>
                  </Table>
                </TableContainer>
              )}
              <Box
                component="pre"
                tabIndex={0}
                role="region"
                aria-label="Formatted calculation JSON"
                sx={{
                  m: 0,
                  p: 1.5,
                  maxWidth: '100%',
                  maxHeight: 280,
                  overflow: 'auto',
                  fontFamily: 'ui-monospace, SFMono-Regular, Menlo, Consolas, monospace',
                  fontSize: '0.75rem',
                  lineHeight: 1.5,
                  whiteSpace: 'pre',
                  bgcolor: 'action.hover',
                  borderRadius: 1,
                  border: '1px solid',
                  borderColor: 'divider',
                }}
              >
                {JSON.stringify(footprint.calculationRecord, null, 2)}
              </Box>
              <Button
                size="small"
                variant="outlined"
                onClick={() => {
                  const blob = new Blob(
                    [JSON.stringify(footprint.calculationRecord, null, 2)],
                    { type: 'application/json' }
                  );
                  const url = URL.createObjectURL(blob);
                  const link = document.createElement('a');
                  link.href = url;
                  link.download = 'transaction-calculation.json';
                  link.click();
                  URL.revokeObjectURL(url);
                }}
              >
                Download calculation JSON
              </Button>
            </Stack>
          </AccordionDetails>
        </Accordion>
      )}
      </Stack>
    </Box>
  );
};

export default TransactionCalculationDetails;
